  for (int i=1;i<=n+1;++i)

	for (int j=1;j<=i;++j) sl[i][j]=add(sl[i-1][j-1],mul(j,sl[i-1][j]));

}



int ans;



void Get_ans(){

  for (int i=0;i<=n;++i){

	int cnt=0,pw=1;

	for (int j=0;j<=i;++j){

	  sadd(cnt,mul(sl[i+1][j+1],pw));

	  smul(pw,pw2[n-i]);

	}

	smul(cnt,mul(Get_c(n,i),Power(2,Power(2,n-i,mod-1))));

	i&1?ssub(ans,cnt):sadd(ans,cnt);

  }

}



void work(){

  Get_pw2();

  Get_inv();

  Get_sl();

  Get_ans();

}



void outo(){

  printf("%d\n",ans);

}



int main(){

  into();

  work();

  outo();

  return 0;

}

