static int32_t A, B, C, D;

static vector<vector<double>> memo;



static double get_concentration(int32_t water, int32_t sugar)

{

	return water + sugar == 0 ? 0.0 : sugar / (water * 100.0 + sugar);

}



static double dp(int32_t water, int32_t sugar)

{

	if (memo[water][sugar] >= 0.0)

		return memo[water][sugar];



	double res = get_concentration(water, sugar);

	res = max(res, dp(water + A, sugar));

	res = max(res, dp(water + B, sugar));

	res = max(res, dp(water, sugar + C));

	res = max(res, dp(water, sugar + D));

	memo[water][sugar] = res;

	return memo[water][sugar];

}



int main()

{

	int32_t E, F;

	cin >> A >> B >> C >> D >> E >> F;



	memo.resize(F + 1);

	for (int32_t i = 0; i < F + 1; i++) {

		memo[i].resize(F + 1);

		fill(begin(memo[i]), end(memo[i]), -1.0);

	}

	for (int32_t water = 0; water < F + 1; water++) {

		for (int32_t sugar = 0; sugar < F + 1; sugar++) {

			if (water * 100 + sugar > F || water * E < sugar)

				memo[water][sugar] = 0.0;

		}

	}



	double _max = dp(0, 0);

	for (int32_t water = 0; water < F + 1; water++) {

		for (int32_t sugar = 0; sugar < F + 1; sugar++) {

			if (memo[water][sugar] == _max && get_concentration(water, sugar) == _max) {

				if (water == 0 && sugar == 0)

					water = A;

				cout << (water * 100 + sugar) << " " << sugar << endl;

