struct SCC{

  Int n;

  vector<vector<Int> > G,rG,T,C;

  vector<Int> vs,used,blg;

  SCC(){}

  SCC(Int n):n(n),G(n),rG(n),used(n),blg(n){}



  void add_edge(Int from,Int to){

    G[from].emplace_back(to);

    rG[to].emplace_back(from);

  }



  void dfs(Int v){

    used[v]=1;

    for(Int u:G[v])

      if(!used[u]) dfs(u);

    vs.emplace_back(v);

  }



  void rdfs(Int v,Int k){

    used[v]=1;

    blg[v]=k;

    C[k].emplace_back(v);

    for(Int u:rG[v])

      if(!used[u]) rdfs(u,k);

  }



  Int build(){

    for(Int v=0;v<n;v++)

      if(!used[v]) dfs(v);



    fill(used.begin(),used.end(),0);

    Int k=0;

    for(Int i=vs.size()-1;i>=0;i--){

      if(!used[vs[i]]){

        T.emplace_back();

        C.emplace_back();

        rdfs(vs[i],k++);

      }

    }

    for(Int v=0;v<n;v++)

      for(Int u:G[v])

        if(blg[v]!=blg[u])

          T[blg[v]].push_back(blg[u]);



    for(Int i=0;i<k;i++){

      sort(T[i].begin(),T[i].end());

      T[i].erase(unique(T[i].begin(),T[i].end()),T[i].end());

    }

    return k;

  }

};





template <typename T>

vector<T> dijkstra(Int s,vector<vector<pair<Int, T> > > & G){  

  const T INF = numeric_limits<T>::max();    

  using P = pair<T, Int>;

  Int n=G.size();

  vector<T> d(n,INF);

  vector<Int> b(n,-1);

  priority_queue<P,vector<P>,greater<P> > q;

  d[s]=0;

  q.emplace(d[s],s);

  while(!q.empty()){

    P p=q.top();q.pop();

    Int v=p.second;

    if(d[v]<p.first) continue;

    for(auto& e:G[v]){

      Int u=e.first;

      T c=e.second;

      if(d[u]>d[v]+c){

        d[u]=d[v]+c;

        b[u]=v;

        q.emplace(d[u],u);

      }

    }

  }

  return d;

}



