  for(Int i=0;i<n;i++){

    if(p[i]==0) continue;

    scc.add_edge(i,i+p[i]);    

  }

  scc.build();



  vector<Int> nx(n,0);

  for(Int v=0;v<n;v++) nx[v]=v+p[v];



  auto calc=

    [&](Int v,auto func)->Int{

      if(nx[v]<0) return nx[v];

      if(p[v]==0) return v;

      if(scc.C[scc.blg[v]].size()>1u) return nx[v]=-1;   

      return nx[v]=func(nx[v],func);

    };  



  using P = pair<Int, Int>;

  vector<vector<P> > G(n);

  for(Int i=0;i+1<n;i++){

    if(scc.C[scc.blg[i]].size()>1u) continue;    

    for(Int j=1;j<=6;j++){

      Int k=min(i+j,n-1);

      Int u=calc(k,calc);

      if(~u) G[i].emplace_back(u,1);

    }

  }



  cout<<dijkstra(0,G)[n-1]<<endl;

  return 0;

}

