#include <bits/stdc++.h>

using namespace std;



vector<int> tree[1<<18];

int a[1<<18];

int ans[1<<18];

int nlow[1<<18];

int n;



void dfs(int v,int p)

{

    auto ptr=lower_bound(nlow, nlow+n+1, a[v]);

    const int plow=*ptr;

    *ptr=a[v];

    ans[v]=lower_bound(nlow, nlow+n+1, INT_MAX)-nlow-1;

    for(int u: tree[v]) if(p!=u) dfs(u,v);

    *ptr=plow;

}



main()

{

    cin>>n;

    for(int i=0; i<n; ++i)

    {

        cin>>a[i];

    }

    for(int i=0; i<n-1; ++i)

    {

        int u,v; cin>>u>>v; --u,--v;

        tree[v].emplace_back(u);

        tree[u].emplace_back(v);

    }



    for(int i=1; i<=n; ++i)

    {

        nlow[i]=INT_MAX;

    }



    dfs(0,-1);



    for(int i=0; i<n; ++i)

    {

        cout << ans[i] << "\n";

    }

}

