template <class lambda_type>

class make_recursive

{

    const lambda_type &func;

public:

    make_recursive(lambda_type &&f) : func(std::move(f)) {}

    template <class... Args> auto operator()(Args &&... args) const

    {

        return func(*this, std::forward<Args>(args)...);

    }

};



main()

{

    int n; cin>>n;

    vector<int> a(n);

    for(auto &e: a) cin>>e;

    vector<vector<int>> tree(n);

    for(int i=0; i<n-1; ++i)

    {

        int u,v; cin>>u>>v; --u,--v;

        tree[v].emplace_back(u);

        tree[u].emplace_back(v);

    }

    vector nlow(n, INT_MAX),ans(n,0);

    make_recursive([&](auto dfs, int v, int p)->void

    {

        auto ptr=lower_bound(begin(nlow), end(nlow), a[v]);

        const int plow=*ptr;

        *ptr=a[v];

        ans[v]=lower_bound(begin(nlow), end(nlow), INT_MAX)-begin(nlow);

        for(int u: tree[v]) if(p!=u) dfs(u,v);

        *ptr=plow;

    })(0,-1);

    for(int e: ans) cout << e << "\n";

}

