template<typename T, int NN>

struct bit {

  typedef std::function<T(T,T)> OP;

  T data_[NN]; // 0-base

  OP& op_;

  T e_;

  std::stack<std::vector<std::pair<int,T>>> ul_;

  bit(OP& op, T e) : op_(op), e_(e) { std::fill_n(data_, NN, e_); }

  int lb(int i){ return i&-i; }

  T query(int i) { // 1-base

    T res = e_;

    while(i > 0) { res = op_(res, data_[i-1]); i -= lb(i); }

    return res;

  }

  void add(int i, T const& v) { // 1-base

    std::vector<std::pair<int,T>> save;

    while(i <= NN) {

      save.emplace_back(i-1, data_[i-1]);

      data_[i-1] = op_(data_[i-1], v);

      i += lb(i);

    }

    ul_.push(save);

  }

  void undo() {

    std::vector<std::pair<int,T>>& save = ul_.top();

    for(auto p: save) data_[p.first] = p.second;

    ul_.pop();

  }

};

bit<int, MAXNN>::OP op = [](int x, int y){ return std::max(x, y); };

bit<int, MAXNN> max_bit(op, 0);



void dfs(int v, int p) {

