vector<int> segtree(sz);

vector<vector<int>> g(nax);

vector<int> a(nax), rs(nax);

int n;





void upd(int idx, int s, int e, int p, int v) {

    if(p<s || e<p || e<s) return;

    if(s==p && e==p) {

        segtree[idx] = v;

        return;

    }

    int mid = s + (e-s)/2;

    int l = 2*idx; int r = l + 1;

    if(p<=mid) {

        upd(l, s, mid, p, v);

    } else {

        upd(r, mid+1, e, p, v);

    }

    segtree[idx] = max(segtree[l], segtree[r]);

}



int get(int idx, int s, int e, int l, int r) {

    if(e<s) return 0;

    if(r<s || e<l) return 0;

    if(l<=s && e<=r) {

        return segtree[idx];

    }

    int mid = s + (e-s)/2;

    int lc = 2*idx; int rc = lc+1;

    int x = get(lc, s, mid, l, r);

    int y = get(rc, mid+1, e, l, r);

    return max(x, y);

}



int get(int idx, int s, int e, int p) {

    return get(1, s, e, p, p);

}



void dfs(int v, int p) {

    int mx = get(1, 0, n-1, 0, a[v]-1);

    rs[v] = mx+1;

    int prev = get(1, 0, n-1, a[v]);

    upd(1, 0, n-1, a[v], max(rs[v], prev));

    for(int u: g[v]) {

        if(u==p) continue;

        dfs(u, v);

    }

    upd(1, 0, n-1, a[v], prev);

}



