template <typename T>

struct SegmentTree {

  int N;

  T init;

  vector<T> dat;

  SegmentTree(int n, T init) : init(init) {

    N = 1;

    while (N < n) N *= 2;

    dat.assign(2*N-1, init);

  }

  void update(int i, T x) {

    i += N - 1;

    dat[i] = x;

    while (i > 0) {

      i = (i - 1) / 2;

      dat[i] = max(dat[i*2+1], dat[i*2+2]);

    }

  }

  // a <= x < b

  T query(int a, int b) { return query(a, b, 0, 0, N); }

  T query(int a, int b, int i, int l, int r) {

    if(r <= a || b <= l) return init;

    if(a <= l && r <= b) return dat[i];

    T vl = query(a, b, i*2+1, l, (l+r)/2);

    T vr = query(a, b, i*2+2, (l+r)/2, r);

    return max(vl, vr);

  }

};



