	{

		if (r <= a || b <= l) { return val; }

		if (a <= l && r <= b) { return value[k]; }



		Type vl = _query(a, b, 2 * k, l, (l + r) / 2);

		Type vr = _query(a, b, 2 * k + 1, (l + r) / 2, r);



		return Calculate()(vl, vr);

	}



