		for (size = 1; size < size_;) { size <<= 1; }



		value = std::vector<Type>(size * 2, val);

	}



	void update(int i, const Type& x)

	{

		i += size; value[i] += x;



		while (i > 1) { i = i / 2; value[i] = Calculate()(value[2 * i], value[2 * i + 1]); }

	}



	Type query(int s, int t) { return _query(s, t, 1, 0, size); }

};



