#include<bits/stdc++.h>

using namespace std;

using Int = long long;

//BEGIN CUT HERE

template<typename T,size_t X>

struct BinaryTrie{

  struct Node{

    bool f;

    size_t cnt;

    Node *p,*l,*r;

    Node(bool f,Node* p):f(f),cnt(0),p(p){l=r=nullptr;}

  };



  T acc;

  Node *root;

  BinaryTrie():acc(0){root=emplace(0,nullptr);}



  inline Node* emplace(bool f,Node* p){

    return new Node(f,p);

  }



  inline size_t count(Node* a){

    return a?a->cnt:0;

  }



  void add(const T b,size_t k=1){

    const T nb=b^acc;

    Node* a=root;

    for(int i=X-1;i>=0;i--){

      bool f=(nb>>i)&1;

      if(!f&&!a->l) a->l=emplace(f,a);

      if( f&&!a->r) a->r=emplace(f,a);

      a=f?a->r:a->l;

    }

    a->cnt+=k;    

    while((a=a->p)) a->cnt=count(a->l)+count(a->r);    

  }



  inline void update(const T b){acc^=b;}



  Node* find(const T b){

    const T nb=b^acc;

    Node* a=root;

    for(int i=X-1;i>=0;i--){

      bool f=(nb>>i)&1;

      a=f?a->r:a->l;

      if(!a) return a;

    }

    return a;

  }



  Node* check(Node *a){

    if(!a||count(a)) return a;

    delete(a);

    return nullptr;

  }



  void sub(Node* a,size_t k=1){

    assert(a&&a->cnt>=k);

    a->cnt-=k;

    while((a=a->p)){

      a->l=check(a->l);

      a->r=check(a->r);

      a->cnt=count(a->l)+count(a->r);

    }

  }



  Node* xmax(const T b){

    assert(count(root));

    const T nb=b^acc;

    Node* a=root;    

    for(int i=X-1;i>=0;i--){

      bool f=(nb>>i)&1;

      a=(!a->l||(!f&&a->r))?a->r:a->l;

    }

    return a;

  }



  int xmin(const T b){

    return xmax(~b&((T(1)<<X)-1));

  }



  Node* ge(Node *a){

    if(a&&(a->r||a->l)) return a->l?a->l:a->r;

    return a;

  }



  Node* next(Node* a){

    while(a->p){

      if(a->p->l==a) return ge(a->p->r);

      a=a->p;

    }

    return nullptr;

  }



  Node* lower_bound(const T b){

    const T nb=b^acc;

    Node* a=root;

    for(int i=X-1;i>=0;i--){

      bool f=(nb>>i)&1;

      if(!f&&a->l){a=a->l;continue;}

      if( f&&a->r){a=a->r;continue;}

      if(f) return next(a);

      return ge(a->r);

    }

    return a;

  }



  int upper_bound(const T b){

    return lower_bound(b+1);

  }



  T val(Node* a){

    T res(0);

    for(int i=0;i<(int)X;i++){

      bool f=(acc>>i)&1;

      res|=(T(a->f)<<i)^f;      

      a=a->p;

    }

    return res^acc;

  }



  Node* find_by_order(size_t k){

    Node *a=root;

    if(count(a)<=k) return nullptr;

    for(int i=X-1;i>=0;i--){

      bool f=(acc>>i)&1;

      if(count(f?a->r:a->l)<=k){

        k-=count(f?a->r:a->l);

        a=f?a->l:a->r;

      }else{

        a=f?a->r:a->l;

      }

    }

    return a;

  }



  size_t order_of_key(const T b){

    const T nb=b^acc;

    Node *a=root;

    size_t res=0;

    for(int i=X-1;i>=0;i--){

      bool f=(nb>>i)&1;

      if(f) res+=count(a->l);      

      a=f?a->r:a->l;

      if(!a) break;

    }

    return res;

  }

};

