		}

		while (t != &nodes[0]) {

			if (t->ch[0]->size < end) {

				end -= t->ch[0]->size + 1;

				if(t->ch[0]!=&nodes[0]) ret = ret + (t->ch[0]->sum + t->value);

				else ret = ret + t->value;

				t = t->ch[1];

				continue;

			}

			t = t->ch[0];

		}

		return ret;

	}

	void show(Node *node) {

		std::cout << "(";

		if (node->ch[0] != &nodes[0]) {

			show(node->ch[0]);

			std::cout << "←";

		}

		std::cout << node->value.e << " " << node->color << " " << node->height;

		if (node->ch[1] != &nodes[0]) {

			std::cout << "→";

			show(node->ch[1]);

		}

		std::cout << ")";

		return;

	}

};

