	std::ios::sync_with_stdio(false);

	std::cin.tie(0);

	avl_tree<SUM> T;

	uint32 n, q;

	std::cin >> n >> q;

	for (uint32 i = 0;i < n;++i) {

		T = T.insert(0, SUM());

	}

	uint32 c, x, y;

	while (q--) {

		std::cin >> c >> x >> y;

