			std::cout << T.range(x - 1, y).e << "\n";

		}

		else {

			//T.show();

			avl_tree<SUM> V = T.erase(x - 1);

			//V.show();

			T = V.insert(x - 1, T.access(x - 1) + SUM(y));

		}

		//T.show();

	}

	return 0;

