template<typename Monoid>

class avl_tree {

	static constexpr uint64 allocsize = (uint64)1 << 14;

	struct node_t {

		node_t *left, *right;

		Monoid value, sum;

		intl32 height;

		uintl32 size, ref;

		void gc(void) {

			left->reset();

			right->reset();

			left = garbage;

			garbage = this;

		}

		void reset(void) {

			if (!(--ref)) gc();

		}

	};

	static node_t *garbage;

	static node_t *data_;

	static node_t nil;

	node_t *root_;

	avl_tree(node_t *root) :root_(root) {

		++root->ref;

	}

	static node_t *alloc(void) {

		if (!garbage) {

			garbage = (node_t *)malloc(allocsize*(uint64)sizeof(node_t));

			uint32 i = allocsize;

			(garbage + i - 1)->left = nullptr;

			while (--i) {

				(garbage + i - 1)->left = (garbage + i);

			}

		}

		node_t *ret = garbage;

		garbage = garbage->left;

		return ret;

	}

	static node_t *make(node_t *l, node_t *r, Monoid &m) {

		node_t *ret = alloc();

		ret->left = l;

		ret->right = r;

		ret->value = m;

		ret->sum = (l->sum + m) + r->sum;

		ret->height = std::max(l->height, r->height) + 1;

		ret->size = l->size + r->size + 1;

		ret->ref = 0;

		++l->ref;

		++r->ref;

		return ret;

	}

	static node_t *adjustR(node_t *n) {

		if (n->right->height - n->left->height < 2) return n;

		if (n->right->right->height + 1 < n->right->height) {

			node_t *t = n->right->left;

			t = make(make(n->left, t->left, n->value), make(t->right, n->right->right, n->right->value), t->value);

			n->gc();

			return t;

		}

		else {

			node_t *t = n->right;

			t = make(make(n->left, t->left, n->value), t->right, t->value);

			n->gc();

			return t;

		}

	}

	static node_t *adjustL(node_t *n) {

		if (n->left->height - n->right->height < 2) return n;

		if (n->left->left->height + 1 < n->left->height) {

			node_t *t = n->left->right;

			t = make(make(n->left->left, t->left, n->left->value), make(t->right, n->right, n->value), t->value);

			n->gc();

			return t;

		}

		else {

			node_t *t = n->left;

			t = make(t->left, make(t->right, n->right, n->value), t->value);

			n->gc();

			return t;

		}

	}

	static node_t *insert_(node_t *n, uint32 position) {

		if (n == &nil) return data_;

		if (n->left->size < position) {

			return adjustR(make(n->left, insert_(n->right, position - n->left->size - 1), n->value));

		}

		else {

			return adjustL(make(insert_(n->left, position), n->right, n->value));

		}

	}

	static node_t *erase_(node_t *n, uint32 position) {

		if (n->left->size > position) {

			return adjustR(make(erase_(n->left, position), n->right, n->value));

		}

		else if (n->left->size < position) {

			return adjustL(make(n->left, erase_(n->right, position - n->left->size - 1), n->value));

		}

		if (n->left == &nil) {

			data_ = n;

			if (n->right == &nil) {

				return &nil;

			}

			else {

				return make(&nil, &nil, n->right->value);

			}

		}

		else {

			if (n->right == &nil) {

				return make(&nil, &nil, n->left->value);

			}

			else {

				node_t *t = erase_(n->right, 0);

				return adjustL(make(n->left, t, data_->value));

			}

		}

	}

	static Monoid more_than(node_t *n, uint32 position) {

		Monoid ret;

		while (n != &nil) {

			if (n->left->size < position) {

				position -= n->left->size + 1;

				n = n->right;

			}

			else {

				ret = (n->value + n->right->sum) + ret;

				n = n->left;

			}

		}

		return ret;

	}

	static Monoid less_than(node_t *n, uint32 position) {

		Monoid ret;

		while (n != &nil) {

			if (n->left->size < position) {

				position -= n->left->size + 1;

				ret = ret + (n->left->sum + n->value);

				n = n->right;

			}

			else {

				n = n->left;

			}

		}

		return ret;

	}

	static void show(node_t *n) {

		std::cout << "(";

		if (n->left != &nil) {

			show(n->left);

			std::cout << "←";

		}

		std::cout << n->value.e << " " << n->height;

		if (n->right != &nil) {

			std::cout << "→";

			show(n->right);

		}

		std::cout << ")";

	}

public:

	avl_tree() :root_(&nil) {

		++nil.ref;

	}

