		++node->ch[0]->height;

		node->ch[0]->color = 1;

		++node->ch[1]->height;

		node->ch[1]->color = 1;

		return node;

	}

	Monoid range(Node *root, uint32 begin, uint32 end) {

		Node *t = root;

		Monoid ret;

		while (1) {

			if (t->ch[0]->size < begin) {

				begin -= t->ch[0]->size + 1;

				end -= t->ch[0]->size + 1;

				t = t->ch[1];

				continue;

			}

			if (t->ch[0]->size < end) {

				end -= t->ch[0]->size + 1;

				ret = t->value;

				root = t->ch[0];

				t = t->ch[1];

				break;

			}

			t = t->ch[0];

		}

		while (root != &nodes[0]) {

			if (root->ch[0]->size < begin) {

				begin -= root->ch[0]->size + 1;

				root = root->ch[1];

				continue;

			}

			if(root->ch[1]!=&nodes[0]) ret = (root->value + root->ch[1]->sum) + ret;

			else ret = root->value + ret;

			root = root->ch[0];

		}

		while (t != &nodes[0]) {

			if (t->ch[0]->size < end) {

				end -= t->ch[0]->size + 1;

				if(t->ch[0]!=&nodes[0]) ret = ret + (t->ch[0]->sum + t->value);

				else ret = ret + t->value;

				t = t->ch[1];

				continue;

			}

			t = t->ch[0];

		}

		return ret;

	}

	void show(Node *node) {

		std::cout << "(";

