		std::cout << "(";

		if (n->left != &nil) {

			show_(n->left);

			std::cout << "←";

		}

		std::cout << n->value.e << " " << n->height;

		if (n->right != &nil) {

			std::cout << "→";

			show_(n->right);

		}

		std::cout << ")";

	}

