	struct node_t {

		node_t *left, *right;

		Monoid value, sum;

		intl32 height;

		uintl32 size, ref;

		void gc(void) {

			left->reset();

			right->reset();

			left = garbage;

			garbage = this;

		}

		void reset(void) {

			if (!(--ref)) gc();

		}

	};

