		root_->reset();

		root_ = other.root_;

		++root_->ref;

		return *this;

	}

	~avl_tree() {

		root_->reset();

	}

	Monoid access(uint32 index) {

		node_t *n = root_;

		while (index != n->left->size) {

			if (n->left->size < index) {

				index -= n->left->size + 1;

				n = n->right;

			}

			else {

				n = n->left;

			}

		}

