long long int cclt(long long int n)

{

    if(n==0)

    {

        return 0;

    }

    long long int rst=0,f=1;

    while(n/f>0)

    {

        rst+=cclt(n%f)+(n/f)*c(n%f);

        f*=10;

    }

    return rst;

}



