const long MOD = 1000000007;



long long kaijo(long a, long b)

{

    if(b==0) {

        return 1;

    }

    else if(b%2==0) {

        long long tmp = kaijo(a, b/2) % MOD;

        return (tmp * tmp) % MOD; 

    }

    else {

        return (kaijo(a, b-1) * a) % MOD;

    }

}



long long st_calc( long a, long b )

{

    long long tmp = 0;



    tmp += a * kaijo(3, b) % MOD;

    if(b>0) {

        tmp += kaijo(3, b-1) * b;

    }



    return (tmp % MOD);

}



