int main(int argc, char *argv[]) {

  // read inputs

  char s[MAX_LEN + 1];

  scanf("%s", s);

  const long n = strlen(s);



  // calculate powers of 3

  long pow3[MAX_LEN + 1] = {};

  pow3[0] = 1;

  for (int i = 1; i <= n; i++) {

    pow3[i] = (pow3[i - 1] * 3) % NUM_MOD;

  }



  // count total number of ?s

  long num_q = 0;

  for (int i = 0; i < n; i++) {

    if (s[i] == '?') {

      num_q++;

    }

  }



  // solve

  long cnt_a = 0, cnt_q = 0, cnt_ab = 0, cnt_aq = 0, cnt_qb = 0, cnt_qq = 0;

  long ans = 0;

  for (int i = 0; i < n; i++) {

    switch (s[i]) {

      case 'A':

        cnt_a++;

        break;

      case 'B':

        cnt_ab += cnt_a;

        cnt_qb += cnt_q;

        break;

      case 'C':

        ans = (ans + cnt_ab * pow3[num_q] +

               cnt_aq * (num_q >= 1 ? pow3[num_q - 1] : 0) +

               cnt_qb * (num_q >= 1 ? pow3[num_q - 1] : 0) +

               cnt_qq * (num_q >= 2 ? pow3[num_q - 2] : 0)) %

              NUM_MOD;

        break;

      case '?':

        ans = (ans + (cnt_ab * (num_q >= 1 ? pow3[num_q - 1] : 0)) % NUM_MOD +

               (cnt_aq * (num_q >= 2 ? pow3[num_q - 2] : 0)) % NUM_MOD +

               (cnt_qb * (num_q >= 2 ? pow3[num_q - 2] : 0)) % NUM_MOD +

               (cnt_qq * (num_q >= 3 ? pow3[num_q - 3] : 0)) % NUM_MOD) %

              NUM_MOD;

        cnt_qq += cnt_q;

        cnt_aq += cnt_a;

        cnt_q++;

        break;

      default:

        printf("something is wrong...\n");

        exit(0);

        break;

    }

  }

  printf("%ld\n", ans);



  return 0;

}

