typedef long long ll;



const ll MOD = 1000000007;



ll modpow(ll x, ll n){

    ll res = 1;

    while(n > 0){

        if(n % 2){

            res = (res * x) % MOD;

        }

        x = (x * x) % MOD;

        n /= 2;

    }

    return res;

}





int main()

{

    string s;

    cin >> s;

    ll q = 0;

    ll sa = 0;

    ll sc = 0;

    ll n = s.size();

    for(int i = 0; i < n; i++){

        if(s[i] == '?'){

            q++;

        }

        if(s[i] == 'A'){

            sa++;

        }

        if(s[i] == 'C'){

            sc++;

        }

    }

    ll a[100001] {0};

    ll c[100001] {sc};

    ll lq[100001] {0};

    ll rq[100001] {q};

    if(s[0] == 'C'){

        c[0] = sc - 1;

    }

    if(s[0] == '?'){

        rq[0] = q - 1;

    }

    for(int i = 1; i < n; i++){

        a[i] = a[i - 1];

        if(s[i - 1] == 'A'){

            a[i]++;

        }

        lq[i] = lq[i - 1];

        if(s[i - 1] == '?'){

            lq[i]++;

        }

        c[i] = c[i - 1];

        if(s[i] == 'C'){

            c[i]--;

        }

        rq[i] = rq[i - 1];

        if(s[i] == '?'){

            rq[i]--;

        }

    }

    ll ans = 0;

    for(int i = 0; i < n; i++){

        ll ansi = 0;

        if(s[i] == 'B'){

            ansi = ((a[i] * c[i]) % MOD) * modpow(3, q) + ((lq[i] * c[i]) % MOD) * modpow(3, q - 1) + ((a[i] * rq[i]) % MOD) * modpow(3, q - 1) + ((lq[i] * rq[i]) % MOD) * modpow(3, q - 2);

        }

        if(s[i] == '?'){

            ansi = ((a[i] * c[i]) % MOD) * modpow(3, q - 1) + ((lq[i] * c[i]) % MOD) * modpow(3, q - 2) + ((a[i] * rq[i]) % MOD) * modpow(3, q - 2) + ((lq[i] * rq[i]) % MOD) * modpow(3, q - 3);

        }

        ans = (ans + ansi) % MOD;

    }

    cout << ans << endl;

}

