  vi32 csum(n + 1);

  vi32 qsum(n + 1);

  rep(i, n) asum[i + 1] += asum[i] + (s[i] == 'A');

  rep(i, n) csum[i + 1] += csum[i] + (s[i] == 'C');

  rep(i, n) qsum[i + 1] += qsum[i] + (s[i] == '?');

