      int a = asum[i];

      int c = csum[n] - csum[i + 1];

      sum += (mint) a * c * exp((mint) 3, qsum[n] - x);

    }

    {

      int a = qsum[i];

      int c = csum[n] - csum[i + 1];

      sum += (mint) a * c * exp((mint) 3, qsum[n] - x - 1);

    }

    {

      int a = asum[i];

      int c = qsum[n] - qsum[i + 1];

      sum += (mint) a * c * exp((mint) 3, qsum[n] - x - 1);

    }

    {

      int a = qsum[i];

      int c = qsum[n] - qsum[i + 1];

      sum += (mint) a * c * exp((mint) 3, qsum[n] - x - 2);

    }

    ans += sum;

  }

  cout << ans << endl;

}

