Weight max_flow(Graph &G,int s,int t,int ff=0){

	Weight flow = 0;

	while(true){

		vector<int> level(G.size(),-1);

		vector<int> iter(G.size(),0);

		bfs(G,level,s);

		if(level[t]<0)break; // もう流せない

		if(ff){

			return dfs(G,level,iter,s,t,1);

		}

		Weight f=0;

		while((f=dfs(G,level,iter,s,t,INF))>0){

			flow+=f;

		}

	}

	return flow;

}





