		Edge(int v, Weight w,int r=0):v(v),w(w),r(r){}

	};

	typedef vector< vector<Edge> > Graph;

	int n, source, sink;

	Graph g;

	Weight flow;

	MaxFlow(int n=0, int s=0, int t=0):n(n), g(n), flow(0), source(s), sink(t){



	}



	void add_edge(int u, int v, Weight cap, Weight revcap=0){

		g[u].emplace_back(v,cap,g[v].size());

		g[v].emplace_back(u,revcap,g[u].size()-1);

	}

	void rem_edge(int u,int v, Weight cap){

		for(auto &e : g[u])if(e.v == v){

			Weight t = min(cap, e.w);

			e.w -= t;

			cap -= t;

			if(cap == 0) return;

		}

		Weight t = cap;

		cap -= maxflow_dinic(u, v, cap);

		if(cap){

			maxflow_dinic(sink, v, cap);

			maxflow_dinic(u, source, cap);

			flow -= cap;

		}

		rem_edge(v, u, t);

	}



	Weight maxflow_dinic(int source, int sink, Weight limit){

		if(source == sink) return limit;

		const Weight inf = numeric_limits<Weight>::max();

		Weight flow = 0;

		while(true){

			vector<int> level(n, -1);

			queue<int> q;

			level[source] = 0;

			q.push(source);

			while(!q.empty()){

				const int u = q.front(); q.pop();

				for(const auto &e : g[u]){

					const int v = e.v;

					if(e.w <= 0 || level[v] >= 0){ continue; }

					level[v] = level[u] + 1;

					q.push(v);

				}

			}

			if(level[sink] < 0){ break; }

			vector<size_t> itr(n, 0);

			while(true){

				function<Weight(int, Weight)> dfs =

					[&](int u, Weight limit) -> Weight{

						if(u == sink) return limit;

						for(; itr[u] < g[u].size(); ++itr[u]){

							auto &e = g[u][itr[u]];

							const int v = e.v;

							if(e.w <= 0 || level[u] >= level[v]){ continue; }

							const Weight diff = dfs(v, min(e.w, limit));

							if(diff > 0){

