						return 0;

					};

				const auto f = dfs(source, limit - flow);

				if(f <= 0) break;

				if((flow += f) == limit) return flow;

			}

		}

		return flow;

	}

	Weight maxflow(){

		return flow += maxflow_dinic(source, sink, numeric_limits<Weight>::max());

	}

};



