        for(int j = 0;j < k;j++){

            int a;

            cin >> a;

            a--;

            tree.unite(i,a+n);

        }

    }



    int r = tree.find(0);



    for(int i = 0;i < n;i++){

        if(tree.find(i) != r){

            cout << "NO" << endl;

            return 0;

        }

    }

    cout << "YES" << endl;



    return 0;

}

