			for (auto u : P[p.second]) {

				if (!usedl[u]) {

					usedl[u] = true;

					q.push({ 0,u });

				}

			}

		}

		else {

			for (auto u : L[p.second]) {

				if (!usedp[u]) {

					usedp[u] = true;

					q.push({ 1,u });

				}

			}

		}

	}

	for (int i = 1; i <= N; i++) {

		if (!usedp[i]) {

			std::cout << "NO" << std::endl;

			return 0;

		}

	}

