ll fac[N],ifac[N];

ll quick_pow(ll a,ll b){

    ll ans=1;a%=mod;

    while(b){

        if(b&1) ans=ans*a%mod;

        a=a*a%mod;

        b>>=1;

    }

    return ans;

}

ll inv(ll x){

    return quick_pow(x,mod-2);

}

