	a = a % mod;

	while (b)

	{

		if (b & 1)

			P = (P * (a % mod)) % mod;

		a = (a * a) % mod;

		b >>= 1;

	}

	return P;

}

ll com(ll n, ll r)

{

	if (n - r > r)

	{

		r = n - r;

	}

	ll i, j, s = 1;

	for (i = 0, j = 1; i < r; ++i)

	{

		s *= n - i;

		for (; j <= r && s % j == 0; j++)

		{

			s /= j;

		}

	}

	return s;

}

