void init()

{

   for(int i = 0; i < maxn; i++)

        f[i] = i, g[i] = i;

}



int getf(int *data, int u)

{

    if(data[u] == u) return u;

    return data[u] = getf(data, data[u]);

}



void Merge(int *data, int u, int v)

{

    int t1 = getf(data, u);

    int t2 = getf(data, v);

    data[t2] = t1;

}



vector<int> root[maxn];

