    for(int i = 0; i < k; i++)

    {

        scanf("%d %d", &u, &v);

        Merge(f, u, v);

    }

    for(int i = 0; i < l; i++)

    {

        scanf("%d %d", &u, &v);

        Merge(g, u, v);

    }



    for(int i = 1; i <= n; i++)

    {

       root[getf(f, i)].push_back(i);

    }

    for(int i = 1;  i <= n; i++)

    {

         p.clear();

        int len = root[i].size();

        for(int j = 0; j < len; j++)

        {

            p[getf(g, root[i][j])]++;

        }

        for(int j = 0; j < len; j++)

