    for(int i=0; i<N; i++) {

        faf[i] = fag[i] = i;

    }

}

int Find(int *f, int x){

    if(f[x] == x) return x;

    else{

        f[x] = Find(f, f[x]);

        return f[x];

    }

}

void Merge(int *f, int x, int y){

    int a = Find(f, x) , b = Find(f, y);

    if(a!=b){

        f[b] = a;

    }

}

