void join(int op, int x, int y) {

    x = find(op,x);

    y = find(op,y);

    if(x == y) return;

    if(peso[op][x] < peso[op][y]) swap(x,y);

    pai[op][y] = x;

    peso[op][x] += peso[op][y];

}



