    for(int i = 0; i < 3; i++)

        for(int j = 0; j <= n; j++) {

            pai[i][j] = j;

            peso[i][j] = 1;

        }

}



int find(int op, int x) {

    return (pai[op][x] == x? x : pai[op][x] = find(op,pai[op][x]));

}



void join(int op, int x, int y) {

    x = find(op,x);

    y = find(op,y);

    if(x == y) return;

    if(peso[op][x] < peso[op][y]) swap(x,y);

    pai[op][y] = x;

    peso[op][x] += peso[op][y];

}



