    }



    while(l--) {

        int a,b; cin >> a >> b;

        if(find(1,a) != find(1,b)) join(1,a,b);

    }



    for(int i = 1; i <= n; i++)

        g[find(0,i)].eb(find(1,i),i);



    for(int i = 1; i <= n; i++) {

        sort(g[i].begin(), g[i].end());

        for(int j = 1; j < g[i].size(); j++)

            if(g[i][j].fi == g[i][j-1].fi)

                join(2,g[i][j].se,g[i][j-1].se);

    }



    for(int i = 1; i <= n; i++) cout << peso[2][find(2,i)] << " ";

    cout << endl;



    return 0;

}

