void upd1(int v, int tl, int tr, int pos,int val){

	if(tl == tr){

		t1[v] = val;

		return;

	}

	int tm = (tl + tr) >> 1;          

	if(pos <= tm)

		upd1(v << 1, tl, tm, pos, val);

	else

		upd1(v << 1 | 1, tm + 1, tr, pos, val);

	t1[v] = min(t1[v << 1], t1[v << 1 | 1]);

}

int get1(int v, int tl, int tr, int l, int r){

	if(r < tl || tr < l)

		return inf;

	if(l <= tl && tr <= r)

		return t1[v];

	int tm = (tl + tr) >> 1;

	return min(get1(v << 1, tl, tm, l, r), get1(v << 1 | 1, tm + 1, tr, l, r));

}

void upd2(int v, int tl, int tr, int pos,int val){

	if(tl == tr){

		t2[v] = val;

		return;

	}

	int tm = (tl + tr) >> 1;          

	if(pos <= tm)

		upd2(v << 1, tl, tm, pos, val);

	else

		upd2(v << 1 | 1, tm + 1, tr, pos, val);

	t2[v] = max(t2[v << 1], t2[v << 1 | 1]);

}

int get2(int v, int tl, int tr, int l, int r){

	if(r < tl || tr < l)

		return -inf;

	if(l <= tl && tr <= r)

		return t2[v];

	int tm = (tl + tr) >> 1;

	return max(get2(v << 1, tl, tm, l, r), get2(v << 1 | 1, tm + 1, tr, l, r));

}

void push(int v){                              

	t[v << 1] = 1ll * t[v << 1] * s[v] % mod;

	s[v << 1] = 1ll * s[v << 1] * s[v] % mod;

	t[v << 1 | 1] = 1ll * t[v << 1 | 1] * s[v] % mod;

	s[v << 1 | 1] = 1ll * s[v << 1 | 1] * s[v] % mod;

	s[v] = 1;

}

void updp(int v, int tl, int tr, int pos, int val){

	if(tl == tr){

		t[v] = (t[v] + val) % mod;

		return;

	}

	push(v);

	int tm = (tl + tr) >> 1;

	if(pos <= tm)

		updp(v << 1, tl, tm, pos, val);

	else

		updp(v << 1 | 1, tm + 1, tr, pos, val);

	t[v] = (t[v << 1] + t[v << 1 | 1]) % mod;	

}

void upds(int v, int tl, int tr, int l, int r){

	if(r < tl || tr < l)

		return;

	if(l <= tl && tr <= r){

		t[v] = (t[v] + t[v]) % mod;

		s[v] = (s[v] + s[v]) % mod;

		return;

