	while (c >= '0' && c <= '9')num = num * 10 + c - '0', c = getchar();

	return num;

}

int cmp(pair<int, int>a, pair<int, int>b)

{

	if (a.second == b.second)return a.first < b.first;

	else return a.second < b.second;

}

int down(int w)

{

	if (tag[w] == inf)return 0;

	t[2 * w] = min(t[2 * w], tag[w]);

	t[2 * w + 1] = min(t[2 * w + 1], tag[w]);

	tag[2 * w] = min(tag[2 * w], tag[w]);

	tag[2 * w + 1] = min(tag[2 * w + 1], tag[w]);

	tag[w] = inf;

	return 0;

}

int change(int w, int l, int r, int x, int y, int v)

{

	if (x <= l && r <= y)

	{

		t[w] = min(t[w], v);

		tag[w] = min(tag[w], v);

		return 0;

	}

	down(w);

	int mid = (l + r) / 2;

	if (x <= mid)change(2 * w, l, mid, x, y, v);

	if (y > mid)change(2 * w + 1, mid + 1, r, x, y, v);

	t[w] = min(t[2 * w], t[2 * w + 1]);

	return 0;

}

int ask(int w, int l, int r, int x)

{

	if (l == r)return t[w];

	down(w);

	int mid = (l + r) / 2;

	if (x <= mid)return ask(2 * w, l, mid, x);

	else return ask(2 * w + 1, mid + 1, r, x);

}

