// ModInt begin



using ll = long long;

template<ll mod>

struct ModInt {

    ll v;

    ll mod_pow(ll x, ll n) const {

        return (!n) ? 1 : (mod_pow((x*x)%mod,n/2) * ((n&1)?x:1)) % mod;

    }

    ModInt(ll a = 0) : v(a >= mod ? a % mod : a) {}

    ModInt operator+ ( const ModInt& b ) const {

        return (v + b.v >= mod ? ModInt(v + b.v - mod) : ModInt(v + b.v));

    }

    ModInt operator- () const {

        return ModInt(-v);

    }

    ModInt operator- ( const ModInt& b ) const {

        return (v - b.v < 0 ? ModInt(v - b.v + mod) : ModInt(v - b.v));

    }

    ModInt operator* ( const ModInt& b ) const {return (v * b.v) % mod;}

    ModInt operator/ ( const ModInt& b ) const {return (v * mod_pow(b.v, mod-2)) % mod;}



    bool operator== ( const ModInt &b ) const {return v == b.v;}

    ModInt& operator+= ( const ModInt &b ) {

        v += b.v;

        if(v >= mod) v -= mod;

        return *this;

    }

    ModInt& operator-= ( const ModInt &b ) {

        v -= b.v;

        if(v < 0) v += mod;

        return *this;

    }

    ModInt& operator*= ( const ModInt &b ) {

        (v *= b.v) %= mod;

        return *this;

    }

    ModInt& operator/= ( const ModInt &b ) {

        (v *= mod_pow(b.v, mod-2)) %= mod;

        return *this;

    }

    ModInt pow(ll x) { return ModInt(mod_pow(v, x)); }

    // operator int() const { return int(v); }

    // operator long long int() const { return v; }

};



template<ll mod>

ostream& operator<< (ostream& out, ModInt<mod> a) {return out << a.v;}

template<ll mod>

istream& operator>> (istream& in, ModInt<mod>& a) {

    in >> a.v;

    return in;

}



// ModInt end



using mint = ModInt<1000000007>;

mint dp[2][100010];

int main() {

    int N, K; cin >> N >> K;



    vector<int> d;

    for(int i=1; i*i<=N; i++) {

        d.push_back(i);

        d.push_back(N/i);

    }

    sort(d.begin(), d.end());

    d.erase(unique(d.begin(), d.end()), d.end());



    int A = d.size();

    vector<int> rng;

    rng.push_back(1);

    for(int i=1; i<A; i++) {

        rng.push_back(d[i] - d[i-1]);

    }



    dp[0][0] = mint(1);

    for(int i=0; i<K; i++) {

        int cur = i % 2, nxt = 1 - cur;

        for(int j=0; j<A; j++) {

            dp[nxt][0  ] += dp[cur][j] * rng[j];

            dp[nxt][A-j] -= dp[cur][j] * rng[j];

        }

        for(int j=0; j<=A; j++) {

            dp[nxt][j+1] += dp[nxt][j];

            dp[cur][j  ] = mint(0);

        }

    }



    mint ans = 0;

    for(int i=0; i<A; i++) ans += dp[K%2][i] * rng[i];

    cout << ans << endl;

    return 0;

}

