ll SQRT(ll n){ll s=1; while(s*s>n||n>=(s+1)*(s+1)){ s=(n/s+s)/2; } return s;}

int main(){

    constexpr ll mod=1e9+7;

    int N,K;cin>>N>>K;

    int s=SQRT(N);

    vector<vector<ll>> dp(K+1,vector<ll>(2*s,0));

    dp[0][0]=1;

    vector<ll> S(2*s+1),cnt(2*s+1);

    REP(j,2*s){

        //cnt[j]:j-1番目の数より大きくj番目の数以下の数がいくつあるか

        if(j<s) cnt[j]=1;

        else{

            int rev = 2*s-j;

            cnt[j]=N/rev-N/(rev+1);

            if(N/rev==s) cnt[j]=0;

        }

    }

    REP(i,K){

        S[0]=0;

        REP(j,2*s){

            S[j+1]=S[j]+dp[i][j];

        }

        REP(j,2*s){

            dp[i+1][j]+=cnt[j]*S[2*s-j];

            dp[i+1][j]%=mod;

        }

    }

    ll ans=0;

    REP(i,2*s){

        ans+=dp[K][i];

        ans%=mod;

    }

    cout<<ans<<endl;

}

