    k /= 2;

  }

  return res;

}



ll pow_mod(ll x, ll k){

  ll res = 1;

  while(k > 0){

    if(k % 2){

      res *= x; res %= MOD;

    }

    x *= x; x %= MOD;

    k /= 2;

  }

  return res;

}



ll inverse(ll x){return pow_mod(x, MOD - 2);};



ll gcd(ll a, ll b){

    if(b == 0) return a;

    return gcd(b, a % b);

}



ll lcm(ll x, ll y){return x / gcd(x, y) * y;};



ll kai_mod(ll x){

  if(x == 0) return 1;

  return x * kai_mod(x-1) % MOD;

}



//約数の列挙O(√n)

vector<ll> divisor(ll n){

    vector<ll> res(0);

    for(ll i = 1; i * i <= n; i++){

        if(n % i == 0){

            res.push_back(i);

            if(i != n/i) res.push_back(n/i);

        }

    }

    sort(res.begin(), res.end());

    return res;

}



