	for (int i = 1; i < N; ++i) {

		long long sum = 0;

		int pos = i;

		while (pos < H) {

			sum += A[pos];

			ans = max(ans, sum);

			pos += i;

		}

		if ((N - 1) % i != 0) {

			pos = (N - 1) - pos;

			while (pos >= i) {

				sum += A[pos];

				ans = max(ans, sum);

				pos -= i;

			}

		}

	}

	cout << ans << endl;

	return 0;

}

