const int N(105);

const double EPS(1e-7);



struct Point {

    int x, y;

    Point(int _x = 0, int _y = 0) {

        x = _x; y = _y;

    }

    void get() {

        scanf("%d%d", &x, &y);

    }

};



int t;

Point p[N];

Point s[2 * N];



vector<Point> ca, cb;



bool cmp(Point p1, Point p2) {

    return p1.x < p2.x || p1.x == p2.x && p1.y < p2.y;

}



int cross(Point a, Point b, Point c) {

    return (b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y);

}



void convexHull(int n, vector<Point> &c) {

    sort(p, p + n, cmp);

    t = 0;

    FOR(i, 0, n) {

        for(; t >= 2 && cross(s[t - 2], s[t - 1], p[i]) <= 0; --t);

        s[t++] = p[i];

    }

    int tt = t - 1;

    for (int i = n - 2; i != -1; --i) {

        for (; t - tt >= 2 && cross(s[t - 2], s[t - 1], p[i]) <= 0; --t);

        s[t++] = p[i];

    }

    c.clear();

    FOR(i, 0, t)

       c.push_back(s[i]);

}



int dcmp(int x) {

    return x == 0 ? 0 : (x > 0 ? 1 : -1);

}



double dis(Point a, Point b) {

    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));

}



bool online(Point a, Point b, Point c) {

    return fabs(dis(a, c) + dis(c, b) - dis(a, b)) < EPS;

}



bool intersect(Point a, Point b, Point c, Point d) {

    return dcmp(cross(a, b, c)) * dcmp(cross(a, b, d)) == -1 && dcmp(cross(c, d, a)) * dcmp(cross(c, d, b)) == -1;

}



