    FOR(i, 0, ca.size()) {

        bool flag = true;

        if (cb.size() == 1) {

            if (dis(ca[i], cb[0]) < EPS) return false;

            continue;

        }

        FOR(j, 1, cb.size()) {

            if (online(cb[j - 1], cb[j], ca[i])) return false;

            flag = flag && cross(cb[j - 1], cb[j], ca[i]) > 0;

        }

        if (flag) return false;

    }

    FOR(i, 0, cb.size()) {

        bool flag = true;

        if (ca.size() == 1) {

            if (dis(cb[i], ca[0]) < EPS) return false;

            continue;

