            flag = flag && cross(ca[j - 1], ca[j], cb[i]) > 0;

        }

        if (flag) return false;

    }

    FOR(i, 1, ca.size())

        FOR(j, 1, cb.size())

            if (intersect(ca[i - 1], ca[i], cb[j - 1], cb[j])) return false;

    return true;

}



