class UnionFind {

public:

	vector <ll> par; 

	vector <ll> siz; 



	// Constructor

	UnionFind(ll sz_) : par(sz_), siz(sz_, 1) {

		for (ll i = 0; i < sz_; ++i) par[i] = i; 

	}

	void init(ll sz_) {

		par.resize(sz_);

		siz.resize(sz_, 1);

		for (ll i = 0; i < sz_; ++i) par[i] = i; 

	}



	// Member Function

	// Find

	ll root(ll x) { 

		while (par[x] != x) {

			x = par[x] = par[par[x]]; 

		}

		return x;

	}



	// Union(Unite, Merge)

	bool merge(ll x, ll y) {

		x = root(x);

		y = root(y);

		if (x == y) return false;



		if (siz[x] < siz[y]) swap(x, y);

		siz[x] += siz[y];

		par[y] = x;

		return true;

	}



	bool issame(ll x, ll y) {

		return root(x) == root(y);

	}



	ll size(ll x) {

		return siz[root(x)];

	}

};

