#include <cstdio>

#include <algorithm>

#include <map>



typedef long long LL;

const int MN = 20;



int N, A[MN];



struct dat {

	dat() {}

	int a, b, c, d;

	dat(int l, int r, int cl, int cr)

		: a(l), b(r), c(cl), d(cr) {}

	friend bool operator < (dat i, dat j) {

		if (i.a != j.a) return i.a < j.a;

		if (i.b != j.b) return i.b < j.b;

		if (i.c != j.c) return i.c < j.c;

		return i.d < j.d;

	}

};

std::map<dat, LL> f;

LL F(int l, int r, int cl, int cr) {

	dat now(l, r, cl, cr);

	if (f.find(now) != f.end()) return f[now];

	if (l > r) return 0;

	LL ans = 0x3f3f3f3f3f3f3f3f;

	for (int i = l; i <= r; ++i)

		ans = std::min(ans, F(l, i - 1, cl, cl + cr) + (LL)A[i] * (cl + cr) + F(i + 1, r, cl + cr, cr));

	return f[now] = ans;

}



int main() {

	scanf("%d", &N);

	for (int i = 0; i < N; ++i) scanf("%d", &A[i]);

	N -= 2;

	printf("%lld\n", F(1, N, 1, 1) + A[0] + A[N + 1]);

	return 0;

}

