#define ll  long long

#define IOS ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);



template <class ...Args>

auto &see(const Args &...args) {return ((cerr << " " << args), ...) << '\n';}

#define bug(...)  cerr << "[ "#__VA_ARGS__" ] = "; see(__VA_ARGS__) << '\n';

//C++17

template<typename... Args>

void read(Args&... args){((cin >> args), ...);}

template<typename... Args>

void write(Args... args){((cout << args << " "), ...);}



ll mod = 1e6 +3 ;

ll power(ll a, ll b)	//a is base, b is exponent

{

    if (b == 0)

        return 1;

    if (b == 1)

        return a;

    if (b % 2 == 1)

        return (power(a, b - 1) * a) % mod;

    ll q = power(a, b / 2);

    return (q * q) % mod;

}



bool comp(pair<int,int>&a ,pair<int,int>&b)

{

    return a.second > b.second ;

}



string s;

int k ,n ;



int main(){

    cin >> n >> k >> s ;



   s[k-1]=tolower(s[k-1]);



   cout << s << endl;





