        if(i !=begin(v)) os << ' ';

        os << *i;

    }

    return os;

}



ll N,m,L,l,X,Y;

ll y;

ll dismin=INF*100;

vector<pair<ll,ll>> A[10007];   //A[i].firstはA[i]枝の先　A[i].secondは重さを表す

ll DKSTR[10007];   //距離の最小値を記入する

ll chek[10007];

ll M[307][307];



void dikstra(ll s,ll t,ll g){   // s始点　t初期値の重さ　g目的地　sからtへの最短距離を返す

    REP(i,0,N+1){

        chek[i]=0;

        DKSTR[i]=LINF;

    }

    DKSTR[s]=t;

    ll key=s;

    priority_queue <pair<ll,ll>> PQ;

    PQ.push(mp(t,s));

    while(PQ.empty()!=1){

        pair<ll,ll> f = PQ.top();

        PQ.pop();

        key=f.second;

        chek[key]=1;

        if(DKSTR[key] < f.first*(-1)){

            continue;

        }

        rep(j,A[key].size()){

            if(A[key][j].second<=L){

                ll v = A[key][j].first;

                if(L-(DKSTR[key]%10000000000)<A[key][j].second){

                    y=((DKSTR[key]/10000000000)+1)*10000000000+A[key][j].second;

                }

                else{

                    y=DKSTR[key]+A[key][j].second;

                }

                if(chek[v]==0 && DKSTR[v]>y){

                    DKSTR[v] = y;

                    PQ.push(mp(DKSTR[v]*(-1),v));

                }

            }

        }

    }

}



int main(){

    cin >> N >> m >> L;

    rep(i,m){

        cin >> X >> Y >> l;   // X=始点　Y=終点  L=重さ

        A[X].pb(mp(Y,l));

        A[Y].pb(mp(X,l));

    }

    ll Q,a,b;

    cin >> Q;

    REP(i,1,N+1){

        dikstra(i,0,i);

        REP(j,1,N+1){

            M[i][j]=DKSTR[j];

        }

    }

    rep(i,Q){

        cin >> a >> b;

        if(M[a][b]==LINF){

            cout << -1 << endl;

        }

        else{

            cout << M[a][b]/10000000000 << endl;

        }

    }

}

