#define INF 1e+17

#define MAX_V 30001

#define KYU 1e+13

#define TP 1e+12

struct edge

{

  ll to;

  ll cost;

};



// <最短距離, 頂点の番号>

using P = pair<ll, ll>;



ll V;

vector<edge> G[MAX_V];

ll d[MAX_V];

ll d2[301][MAX_V];

void dijkstra(ll s, ll L)

{

  priority_queue<P, vector<P>, greater<P>> que;



  fill(d, d + V, INF);

  d[s] = KYU + TP - L;



  que.push(P(d[s], s));



  while (!que.empty())

  {

    P p = que.top();



    que.pop();



    ll v = p.second;



    if (d[v] < p.first)

      continue;



    for (ll i = 0; i < G[v].size(); ++i)

    {

      edge e = G[v][i];



      ll tpcost = d[v] + e.cost;

      ll tpcost2 = tpcost % (ll)KYU;



      if (tpcost2 > TP)

      {

        tpcost = ((tpcost / (ll)KYU) + 1) * KYU + TP - L + e.cost;

      }



      if (d[e.to] > tpcost)

      {

        d[e.to] = tpcost;



        que.push(P(d[e.to], e.to));

      }

    }

  }

}



int main()

{

  ll N, M, L;

  cin >> N >> M >> L;

  V = N;

  for (int i = 0; i < M; ++i)

  {

    int a, b, c;



    cin >> a >> b >> c;

    if (c <= L)

    {

      edge e = {b - 1, c};

      G[a - 1].push_back(e);

      edge e2 = {a - 1, c};

      G[b - 1].push_back(e2);

    }

  }



  ll Q;

  cin >> Q;

  ll s[Q], t[Q];

  FOR(i, 0, Q - 1)

  {

    cin >> s[i] >> t[i];

    s[i]--;

    t[i]--;

  }



  FOR(i, 0, N - 1)

  {

    dijkstra(i, L);



    FOR(j, 0, N - 1)

    {

      d2[i][j] = d[j];

    }

  }



  FOR(i, 0, Q - 1)

  {



    if (d2[s[i]][t[i]] == INF)

    {

      cout << -1 << endl;

    }

    else

    {

      cout << (ll)(d2[s[i]][t[i]] / KYU) - 1 << endl;

    }

  }

}

