    bool issame(int x, int y)

    {

        return root(x) == root(y);

    }

    //AとBをくっ付ける

    bool connect(int A, int B)

    {

        //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける

        A = root(A);

        B = root(B);

        if (A == B)

        {

            //すでにくっついてるからくっ付けない

            return false;

        }



        //大きい方(A)に小さいほう(B)をくっ付けたい

        //大小が逆だったらひっくり返しちゃう。

        if (size(A) < size(B))

            swap(A, B);



        //Aのサイズを更新する

        Parent[A] += Parent[B];

        //Bの親をAに変更する

        Parent[B] = A;



        return true;

    }

};



