typedef pair<P,ll> T;



void dijkstra(int s){

    priority_queue<T,vector<T>,greater<T>> pq;

    reh[s][s]=0,d[s][s]=0;

    pq.push(T{{reh[s][s],d[s][s]},s});

    while(pq.size()){

        T t=pq.top();

        pq.pop();

        int V=t.second;

        if(make_pair(reh[s][V],d[s][V])<t.first){

            continue;

        }

        rep(i,G[V].size()){

