	q.push(make_pair(make_pair(0, l), v));



	dis[v][v] = make_pair(0, l);



	while(!q.empty()){



		long long t = -q.top().first.first, c = q.top().first.second, x = q.top().second;



		q.pop();



		if(dis[v][x].first == t && dis[v][x].second == c){



			for(long long i = 0; i < (long long)ed[x].size(); i++){



				long long tx = t + (ed[x][i].second > c), cx = (ed[x][i].second > c) ? (l - ed[x][i].second) : (c - ed[x][i].second), xx = ed[x][i].first;



				if(cx < 0) continue;

				else if((dis[v][xx].first == -1) || ((dis[v][xx].first > tx) || ((dis[v][xx].first == tx) && (dis[v][xx].second < cx)))){

					q.push(make_pair(make_pair(-tx, cx), xx));

					dis[v][xx].first = tx;

					dis[v][xx].second = cx;

				}

			}

		}

	}

