    D() : cnt(iinf), tank(0) {}

    D(int c, ll t) : cnt(c), tank(t) {}

    bool operator<(const D &d) const {

        return cnt < d.cnt || (cnt == d.cnt && tank > d.tank);

    }

    bool operator>(const D &d) const {

        return !(cnt == d.cnt && tank == d.tank) && !(*this < d);

    }

    D &operator+=(ll cost) {

