#include <bits/stdc++.h>

using namespace std;

typedef long long ll;



#define INF 1e8

#define MAX_V 400



struct status {

    int cnt;

    ll fuel;

};

bool operator<(const status& x0, const status& x1) {

    return (x0.cnt == x1.cnt ? x0.fuel > x1.fuel : x0.cnt < x1.cnt);  //<で昇順

}

status d[MAX_V][MAX_V];

bool visited[MAX_V];

ll cost[MAX_V][MAX_V];

ll V, E, L;



// 頂点rからの最小距離

void dijkstra(int r) {

    for (int i = 0; i < V; i++) {

        d[r][i] = (status){(int)INF, 0};

    }

    fill(visited, visited + MAX_V, false);

    d[r][r] = (status){0, L};



    while (true) {

        int v = -1;

        for (int u = 0; u < V; u++) {

            if (!visited[u] && (v == -1 || d[r][u] < d[r][v])) v = u;

        }

        if (v == -1) break;

        visited[v] = true;



        for (int u = 0; u < V; u++) {

            ll remain = d[r][v].fuel;

            if (remain >= cost[v][u])

                d[r][u] = min(d[r][u], (status){d[r][v].cnt, remain - cost[v][u]});

            else if (L >= cost[v][u])

                d[r][u] = min(d[r][u], (status){d[r][v].cnt + 1, L - cost[v][u]});

        }

    }

}



int main() {

    cin >> V >> E >> L;

    fill(cost[0], cost[MAX_V], 1e18);

    for (int i = 0; i < E; i++) {

        int a, b;

        ll c;

        cin >> a >> b >> c;

        a--, b--;

        cost[a][b] = c;

        cost[b][a] = c;

    }

    for (int i = 0; i < V; i++) {

        dijkstra(i);

    }

    int q;

    cin >> q;

    for (int i = 0; i < q; i++) {

        int s, t;

        cin >> s >> t;

        s--, t--;

        if (d[s][t].cnt == INF)

            cout << -1 << endl;

        else

            cout << d[s][t].cnt << endl;

    }

    return 0;

}

