inline int to(int x, int y, int c) {

    return x * c + y;

}

int build(int x, int n, int lf, int rt) {

    if (lf == rt) {

        return t[to(x, n, c * 4)] = a[to(x, lf, c)];

    }

    int mid = (lf + rt) / 2;

    return t[to(x, n, c * 4)] = min(build(x, n * 2, lf, mid), build(x, n * 2 + 1, mid + 1, rt));

}



int query(int x, int n, int lf, int rt, int x1, int x2) {

    //printf("%d %d\n", x1, x2);

    if (lf == x1 && rt == x2) {

        //printf("%d %d %d: %d\n", x, n, c * 4, to(x, n, c * 4));

        return t[to(x, n, c * 4)];

    }

    int mid = (lf + rt) / 2;

    if (mid >= x2) {

        return query(x, n * 2, lf, mid, x1, x2);

    } else if (mid < x1) {

        return query(x, n * 2 + 1, mid + 1, rt, x1, x2);

    }

    return min(query(x, n * 2, lf, mid, x1, mid), query(x, n * 2 + 1, mid + 1, rt, mid + 1, x2));

}



