using namespace std;



typedef long long LL;



#define INF 0x7fffffff

#define MAX 1048576

#define MAXN 65535

#define MAXLg 16

#define MAXQ 20000



int A[MAX],Log[MAXN + 1],tableMin[MAXN][MAXLg];



void makeRMinQ(int *a,int s,int t){

	int n = t - s;

	for (int i = s; i < t; ++i) tableMin[i - s][0] = a[i];

	for (int j = 1; (1 << j) <= n; ++j)

		for (int i = s; i + (1 << j) <= t; ++i)

			tableMin[i - s][j] = min(tableMin[i - s][j - 1], tableMin[i - s + (1 << (j - 1))][j - 1]);

}



int QueryMin(int x,int y){

	int p = Log[y - x + 1];

	return min(tableMin[x][p],tableMin[y - (1 << p) + 1][p]);

}



struct query{

    int x1, y1;

    int x2, y2;

}fQ[MAXQ];



int Res[MAXQ];



int main() {

	for (int i = 0, x = 0, cd = 2; i <= MAXN; ++x, cd <<= 1)

		while (i <= MAXN && i < cd)

		    Log[++i] = x;

	int R, C, Q;

	while(scanf("%d%d%d",&R,&C,&Q), R){

        if (R <= C){

            for (int i = 0; i < R; ++i)

                for (int j = 0; j < C; ++j)

                    scanf("%d", &A[i * C + j]);

            for (int q = 0; q < Q; ++q)

                scanf("%d%d%d%d", &fQ[q].x1, &fQ[q].y1, &fQ[q].x2, &fQ[q].y2);

        }else{

            for (int i = 0; i < R; ++i)

                for (int j = 0; j < C; ++j)

                    scanf("%d", &A[j * R + i]);

            swap(R, C);

            for (int q = 0; q < Q; ++q){

                scanf("%d%d%d%d", &fQ[q].x1, &fQ[q].y1, &fQ[q].x2, &fQ[q].y2);

                swap(fQ[q].x1, fQ[q].y1);

                swap(fQ[q].x2, fQ[q].y2);

            }

        }

        for (int q = 0;q < Q; ++q)

            Res[q] = INF;

        int fC = (C-1) / MAXN+1;

        for (int i = 0; i < R; ++i){

            for (int j = 0, k = 0; j < fC; ++j){

                int nk = min(C, k + MAXN);

                makeRMinQ(A, i * C + k, i * C + nk);

                for (int q = 0; q < Q; ++q){

                    if (i < fQ[q].x1 || fQ[q].x2 < i)

                        continue;

                    int cs = max(fQ[q].y1,k);

                    int ct = min(fQ[q].y2,nk - 1);

                    if (cs > ct) continue;

                    Res[q] = min(Res[q],QueryMin(cs - k,ct - k));

                }

                k = nk;

            }

        }

        for (int q = 0; q < Q; ++q)

            printf("%d\n", Res[q]);

    }

    return 0;

}

