long long int sizex;

long long int sizey;

long long int const2d;

unsigned int grid[10000000];



void update(long long int x, long long int y, unsigned int t) {

    x += sizex-1;

    y += sizey-1;



    grid[const2d*y+x] = t;

    while (y >= 0) {

        long long int x_ = x;



        while (x_ > 0) {

            x_ = (x_-1)/2;

            grid[const2d*y+x_] = min(grid[const2d*y+x_*2+1], grid[const2d*y+x_*2+2]);

        }

        if (y == 0) break;



        y = (y-1)/2;

        grid[const2d*y+x] = min(grid[const2d*(y*2+1)+x], grid[const2d*(y*2+2)+x]);

    }

}



unsigned int _get_min(unsigned int *vec, int wishl, int wishr, long long int k, int watchl, int watchr) {

    int mid;

    unsigned int lval, rval;



    if (wishr <= watchl || watchr <= wishl) return INF;

    if (wishl <= watchl && watchr <= wishr) {

        return vec[k];

    }



    mid = (watchl+watchr)/2;

    lval = _get_min(vec, wishl, wishr, k*2+1, watchl, mid);

    rval = _get_min(vec, wishl, wishr, k*2+2, mid, watchr);

    return min(lval, rval);

}



unsigned int get_min(int wishl, int wishr, int wishu, int wishd, long long int k, int watchu, int watchd) {

    int mid;

    unsigned int uval, dval;



    if (wishd <= watchu || watchd <= wishu) return INF;

