    }



    mid = (watchu+watchd)/2;

    uval = get_min(wishl, wishr, wishu, wishd, k*2+1, watchu, mid);

    dval = get_min(wishl, wishr, wishu, wishd, k*2+2, mid, watchd);

    return min(uval, dval);

}



int main() {

