        scanf("%d %d %d", &r, &c, &q);

        if (r == 0 && c == 0 && q == 0) return 0;



        sizex = 1;

        while (sizex < c) sizex *= 2;

        sizey = 1;

        while (sizey < r) sizey *= 2;

        const2d = sizex*2-1;



        for (int i=0; i<r; i++) {

            for (int j=0; j<c; j++) {

                unsigned int g;



                scanf("%u", &g);

                update(j, i, g);

            }

        }



        for (int i=0; i<q; i++) {

            int r1, r2;

            int c1, c2;



            scanf("%d %d %d %d", &r1, &c1, &r2, &c2);

